def cmp_semver(a, str_b):
    """
    Compare two SemVer 2.0.0 version strings.
    Returns -1 if a < b, 0 if a == b, 1 if a > b.
    """
    def parse_semver(s):
        # Strip build metadata
        s = s.split('+')[0]

        # Split off pre-release
        if '-' in s:
            core, prerelease = s.split('-', 1)
        else:
            core, prerelease = s, None

        # Parse core version
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1])
        patch = int(parts[2])

        # Parse pre-release identifiers
        if prerelease is not None:
            identifiers = prerelease.split('.')
        else:
            identifiers = None

        return (major, minor, patch, identifiers)

    def compare_identifier(id_a, id_b):
        """
        Compare two pre-release identifiers.
        Numeric identifiers compare numerically and sort before alphanumeric.
        Alphanumeric identifiers compare lexically (ASCII sort).
        """
        a_is_numeric = id_a.isdigit()
        b_is_numeric = id_b.isdigit()

        if a_is_numeric and b_is_numeric:
            num_a = int(id_a)
            num_b = int(id_b)
            if num_a < num_b:
                return -1
            elif num_a > num_b:
                return 1
            else:
                return 0
        elif a_is_numeric and not b_is_numeric:
            # Numeric sorts before alphanumeric
            return -1
        elif not a_is_numeric and b_is_numeric:
            # Alphanumeric sorts after numeric
            return 1
        else:
            # Both alphanumeric: lexical comparison
            if id_a < id_b:
                return -1
            elif id_a > id_b:
                return 1
            else:
                return 0

    a_parsed = parse_semver(a)
    b_parsed = parse_semver(str_b)

    a_major, a_minor, a_patch, a_pre = a_parsed
    b_major, b_minor, b_patch, b_pre = b_parsed

    # Compare major
    if a_major < b_major:
        return -1
    elif a_major > b_major:
        return 1

    # Compare minor
    if a_minor < b_minor:
        return -1
    elif a_minor > b_minor:
        return 1

    # Compare patch
    if a_patch < b_patch:
        return -1
    elif a_patch > b_patch:
        return 1

    # Major, minor, patch are equal. Now compare pre-release.
    # A version WITHOUT pre-release has HIGHER precedence than one WITH pre-release.
    if a_pre is None and b_pre is None:
        return 0
    elif a_pre is None and b_pre is not None:
        # a has no pre-release, b does -> a > b
        return 1
    elif a_pre is not None and b_pre is None:
        # a has pre-release, b does not -> a < b
        return -1
    else:
        # Both have pre-release identifiers
        a_ids = a_pre.split('.')
        b_ids = b_pre.split('.')

        min_len = min(len(a_ids), len(b_ids))

        for i in range(min_len):
            cmp = compare_identifier(a_ids[i], b_ids[i])
            if cmp != 0:
                return cmp

        # All compared identifiers are equal.
        # The one with more identifiers has higher precedence.
        if len(a_ids) < len(b_ids):
            return -1
        elif len(a_ids) > len(b_ids):
            return 1
        else:
            return 0
