class LFUCache:
    def __init__(self, capacity: int):
        self.capacity = capacity
        self.size = 0
        self.min_freq = 0
        self.key_to_node = {}
        self.freq_to_keys = {}  # freq -> OrderedDict of keys in LRU order

    def _remove_key(self, key):
        if key not in self.key_to_node:
            return
        node = self.key_to_node[key]
        freq = node[1]
        val = node[0]
        # Remove from freq_to_keys
        if freq in self.freq_to_keys:
            self.freq_to_keys[freq].pop(key, None)
            if not self.freq_to_keys[freq]:
                del self.freq_to_keys[freq]
                if self.min_freq == freq:
                    self.min_freq = freq + 1
        del self.key_to_node[key]
        self.size -= 1

    def _add_key(self, key, value):
        if key in self.key_to_node:
            # Update existing key
            node = self.key_to_node[key]
            old_freq = node[1]
            # Remove from old freq bucket
            if old_freq in self.freq_to_keys:
                self.freq_to_keys[old_freq].pop(key, None)
                if not self.freq_to_keys[old_freq]:
                    del self.freq_to_keys[old_freq]
                    if self.min_freq == old_freq:
                        self.min_freq = old_freq + 1
            # Add to new freq bucket
            new_freq = old_freq + 1
            self.key_to_node[key] = (value, new_freq)
            if new_freq not in self.freq_to_keys:
                self.freq_to_keys[new_freq] = {}
            self.freq_to_keys[new_freq][key] = True
            # Update min_freq
            if self.min_freq > new_freq:
                self.min_freq = new_freq
        else:
            # Add new key
            if self.size >= self.capacity:
                # Evict from min_freq bucket
                if self.min_freq in self.freq_to_keys and self.freq_to_keys[self.min_freq]:
                    # Pop the least recently used (first item)
                    evict_key = next(iter(self.freq_to_keys[self.min_freq]))
                    self._remove_key(evict_key)
            self.key_to_node[key] = (value, 1)
            if 1 not in self.freq_to_keys:
                self.freq_to_keys[1] = {}
            self.freq_to_keys[1][key] = True
            self.min_freq = 1
            self.size += 1

    def get(self, key: int) -> int:
        if key not in self.key_to_node:
            return -1
        node = self.key_to_node[key]
        val, freq = node
        # Remove from current freq bucket
        if freq in self.freq_to_keys:
            self.freq_to_keys[freq].pop(key, None)
            if not self.freq_to_keys[freq]:
                del self.freq_to_keys[freq]
                if self.min_freq == freq:
                    self.min_freq = freq + 1
        # Add to new freq bucket
        new_freq = freq + 1
        self.key_to_node[key] = (val, new_freq)
        if new_freq not in self.freq_to_keys:
            self.freq_to_keys[new_freq] = {}
        self.freq_to_keys[new_freq][key] = True
        if self.min_freq > new_freq:
            self.min_freq = new_freq
        return val

    def put(self, key: int, value: int) -> None:
        if self.capacity == 0:
            return
        self._add_key(key, value)
