import re
from datetime import datetime, timedelta


def _parse_field(field, min_val, max_val, name):
    """Parse a single cron field and return a set of valid values."""
    values = set()
    parts = field.split(',')
    for part in parts:
        part = part.strip()
        if not part:
            raise ValueError(f"Empty part in {name} field")

        # Check for step
        if '/' in part:
            range_part, step_str = part.split('/', 1)
            try:
                step = int(step_str)
            except ValueError:
                raise ValueError(f"Invalid step in {name} field: {step_str}")
            if step <= 0:
                raise ValueError(f"Step must be positive in {name} field")
        else:
            range_part = part
            step = 1

        if range_part == '*':
            start, end = min_val, max_val
        elif '-' in range_part:
            a, b = range_part.split('-', 1)
            try:
                start = int(a)
                end = int(b)
            except ValueError:
                raise ValueError(f"Invalid range in {name} field: {range_part}")
            if start > end:
                raise ValueError(f"Invalid range in {name} field: {range_part}")
        else:
            try:
                val = int(range_part)
            except ValueError:
                raise ValueError(f"Invalid value in {name} field: {range_part}")
            if step == 1:
                if min_val <= val <= max_val:
                    values.add(val)
                else:
                    raise ValueError(f"Value out of range in {name} field: {val}")
                continue
            else:
                # For a single value with step, it's just that value
                if min_val <= val <= max_val:
                    values.add(val)
                else:
                    raise ValueError(f"Value out of range in {name} field: {val}")
                continue

        # Now handle range with step
        if start < min_val or end > max_val:
            raise ValueError(f"Range out of bounds in {name} field: {range_part}")
        for v in range(start, end + 1, step):
            values.add(v)

    if not values:
        raise ValueError(f"No valid values in {name} field")
    return values


def next_fire(expr, after):
    """
    Return the next datetime strictly after `after` at which a 5-field cron
    expression fires. Seconds and microseconds are zero.

    Fields: minute hour day-of-month month day-of-week
    Day-of-week: 0-6, 0 = Sunday.

    Standard day rule: if both day-of-month and day-of-week are restricted
    (neither is '*'), fire on days matching EITHER. If only one is restricted,
    only that one applies.
    """
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"Expected 5 fields, got {len(fields)}")

    minute_f, hour_f, dom_f, month_f, dow_f = fields

    minutes = _parse_field(minute_f, 0, 59, "minute")
    hours = _parse_field(hour_f, 0, 23, "hour")
    doms = _parse_field(dom_f, 1, 31, "day-of-month")
    months = _parse_field(month_f, 1, 12, "month")
    dows = _parse_field(dow_f, 0, 6, "day-of-week")

    # Determine if dom or dow is restricted (not '*')
    dom_restricted = dom_f.strip() != '*'
    dow_restricted = dow_f.strip() != '*'

    # Start from the next minute after `after`
    # We need strictly after `after`, so start from after + 1 minute,
    # but with seconds and microseconds zero.
    # Actually, let's start from the next minute boundary strictly after `after`.
    # If after is 10:30:00.000000, the next candidate is 10:31:00.
    # If after is 10:30:30.000000, the next candidate is 10:31:00.
    # So we round up to the next minute.

    # Start from after, truncate to minute, then add 1 minute if we're at or past
    # Actually, simpler: start from after, set seconds/microseconds to 0,
    # then if the resulting datetime is <= after, add 1 minute.

    start = after.replace(second=0, microsecond=0)
    if start <= after:
        start += timedelta(minutes=1)

    # Now iterate forward
    # To avoid infinite loops, set a reasonable upper bound (e.g., 10 years)
    max_iterations = 10 * 366 * 24 * 60  # ~10 years of minutes

    current = start

    for _ in range(max_iterations):
        if current.month not in months:
            # Jump to the first day of the next month
            if current.month == 12:
                current = current.replace(year=current.year + 1, month=1, day=1, hour=0, minute=0)
            else:
                current = current.replace(month=current.month + 1, day=1, hour=0, minute=0)
            continue

        if current.day not in doms and current.weekday() not in dows:
            # Check the day rule
            if dom_restricted and dow_restricted:
                # Either dom or dow must match
                if current.day not in doms and current.weekday() not in dows:
                    current += timedelta(days=1)
                    current = current.replace(hour=0, minute=0)
                    continue
            elif dom_restricted:
                if current.day not in doms:
                    current += timedelta(days=1)
                    current = current.replace(hour=0, minute=0)
                    continue
            elif dow_restricted:
                if current.weekday() not in dows:
                    current += timedelta(days=1)
                    current = current.replace(hour=0, minute=0)
                    continue
            else:
                # Neither restricted, so any day is fine
                pass

        if current.hour not in hours:
            # Jump to next hour
            current = current.replace(minute=0)
            current += timedelta(hours=1)
            continue

        if current.minute not in minutes:
            current += timedelta(minutes=1)
            continue

        # All fields match
        return current

    raise ValueError("Could not find next fire time within search limit")
