class TokenBucket:
    def __init__(self, capacity, refill_per_sec, clock):
        self.capacity = capacity
        self.refill_per_sec = refill_per_sec
        self.clock = clock
        self.tokens = float(capacity)
        self.last_time = self.clock()

    def take(self, n=1):
        if n > self.capacity:
            return False
        now = self.clock()
        if now < self.last_time:
            now = self.last_time
        elapsed = now - self.last_time
        if elapsed > 0:
            self.tokens = min(self.capacity, self.tokens + self.refill_per_sec * elapsed)
        self.last_time = now
        if self.tokens >= n:
            self.tokens -= n
            return True
        return False
