def deep_copy(obj):
    """Return a deep copy of a structure built from dicts, lists, sets, tuples and scalars.
    Preserves the sharing graph and handles reference cycles."""
    # Track objects we've already copied to handle cycles and sharing
    memo = {}

    def _copy(o):
        # Handle immutable scalars
        if o is None or isinstance(o, (int, float, bool, str)):
            return o

        # Check if we've already copied this object (handles cycles and sharing)
        if id(o) in memo:
            return memo[id(o)]

        if isinstance(o, dict):
            # Create a new dict and store it in memo before copying contents
            new_dict = {}
            memo[id(o)] = new_dict
            for k, v in o.items():
                new_k = _copy(k)
                new_v = _copy(v)
                new_dict[new_k] = new_v
            return new_dict

        elif isinstance(o, list):
            new_list = []
            memo[id(o)] = new_list
            for item in o:
                new_list.append(_copy(item))
            return new_list

        elif isinstance(o, set):
            new_set = set()
            memo[id(o)] = new_set
            for item in o:
                new_set.add(_copy(item))
            return new_set

        elif isinstance(o, tuple):
            new_tuple = tuple()
            memo[id(o)] = new_tuple
            for item in o:
                new_tuple = new_tuple + (_copy(item),)
            return new_tuple

        else:
            # For other types, return as-is (treat as scalar/immutable)
            return o

    return _copy(obj)
