def to_base(n, alphabet):
    if n == 0:
        return alphabet[0]
    negative = n < 0
    n = abs(n)
    base = len(alphabet)
    digits = []
    while n > 0:
        n, r = divmod(n, base)
        digits.append(alphabet[r])
    if negative:
        digits.append('-')
    return ''.join(reversed(digits))


def from_base(s, alphabet):
    if not s:
        raise ValueError("empty string")
    alphabet_set = set(alphabet)
    negative = False
    if s[0] == '-':
        negative = True
        s = s[1:]
        if not s:
            raise ValueError("empty string after sign")
    for ch in s:
        if ch not in alphabet_set:
            raise ValueError(f"character {ch!r} not in alphabet")
    base = len(alphabet)
    n = 0
    for ch in s:
        n = n * base + alphabet.index(ch)
    return -n if negative else n
