import heapq
from itertools import count


def merge_sorted(*iterables):
    """Merge several already-sorted iterables into a single ascending iterator.

    Stable: equal values are emitted in source order.
    Lazy and memory-bounded: holds at most one pending item per source.
    """
    if not iterables:
        return iter(())

    # Create a counter for tie-breaking to ensure stability (source order)
    counter = count()

    # Build initial heap with first element from each iterable
    heap = []
    for i, it in enumerate(iterables):
        try:
            val = next(it)
            heap.append((val, i, it))
        except StopIteration:
            pass

    if not heap:
        return iter(())

    heapq.heapify(heap)

    while heap:
        val, source_idx, it = heapq.heappop(heap)
        yield val
        try:
            next_val = next(it)
            heapq.heappush(heap, (next_val, source_idx, it))
        except StopIteration:
            pass
