import heapq

def shortest_path(graph, src, dst):
    if src == dst:
        return (0, [src])

    # dist[node] = (cost, num_edges, path_tuple)
    # We want to minimize cost first, then num_edges, then lexicographic path
    # But storing full paths is expensive. Let's think differently.

    # Actually, for tie-breaking on lexicographic path, we need to be careful.
    # Standard Dijkstra with heap: we push (cost, num_edges, path_tuple, node)
    # But path_tuple can be very long. For 200000 nodes, this could be problematic.

    # Alternative: we can store the predecessor and reconstruct, but tie-breaking
    # on lexicographic path makes this tricky because we need to compare paths.

    # Let's use: dist[node] = (cost, num_edges, path_tuple)
    # When we find a better path, we update. "Better" means:
    # lower cost, or same cost but fewer edges, or same cost and edges but lexicographically smaller path.

    INF = float('inf')
    dist = {}
    # heap entries: (cost, num_edges, path_tuple, node)
    heap = []

    initial_path = (src,)
    dist[src] = (0, 0, initial_path)
    heapq.heappush(heap, (0, 0, initial_path, src))

    while heap:
        cost, num_edges, path_tuple, node = heapq.heappop(heap)

        # Check if this is still the best known for this node
        if node in dist:
            best_cost, best_edges, best_path = dist[node]
            if cost > best_cost:
                continue
            if cost == best_cost:
                if num_edges > best_edges:
                    continue
                if num_edges == best_edges:
                    if path_tuple > best_path:
                        continue
                else:
                    # num_edges < best_edges, this is better
                    pass
            else:
                # cost < best_cost, this is better
                pass

        # If we reached dst, we can return since heap is ordered by (cost, edges, path)
        if node == dst:
            return (cost, list(path_tuple))

        # Explore neighbors
        if node not in graph:
            continue

        for neighbor, weight in graph[node]:
            new_cost = cost + weight
            new_edges = num_edges + 1
            new_path = path_tuple + (neighbor,)

            if neighbor not in dist:
                dist[neighbor] = (new_cost, new_edges, new_path)
                heapq.heappush(heap, (new_cost, new_edges, new_path, neighbor))
            else:
                old_cost, old_edges, old_path = dist[neighbor]
                # Check if new path is better
                if new_cost < old_cost:
                    dist[neighbor] = (new_cost, new_edges, new_path)
                    heapq.heappush(heap, (new_cost, new_edges, new_path, neighbor))
                elif new_cost == old_cost:
                    if new_edges < old_edges:
                        dist[neighbor] = (new_cost, new_edges, new_path)
                        heapq.heappush(heap, (new_cost, new_edges, new_path, neighbor))
                    elif new_edges == old_edges:
                        if new_path < old_path:
                            dist[neighbor] = (new_cost, new_edges, new_path)
                            heapq.heappush(heap, (new_cost, new_edges, new_path, neighbor))

    return (None, [])
