import heapq

def topo_lex(graph):
    # Collect all nodes
    nodes = set(graph.keys())
    for succs in graph.values():
        nodes.update(succs)

    if not nodes:
        return []

    # Build in-degree: for each node, how many predecessors it has
    # graph maps node -> list of successors (nodes that depend on it)
    # So if u -> v (v depends on u), then u is a predecessor of v
    in_degree = {node: 0 for node in nodes}
    # adjacency: predecessor -> list of successors
    adj = {node: [] for node in nodes}

    for u, succs in graph.items():
        for v in succs:
            adj[u].append(v)
            in_degree[v] += 1

    # Initialize heap with all nodes having in_degree 0
    heap = []
    for node in nodes:
        if in_degree[node] == 0:
            heapq.heappush(heap, node)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for v in adj[node]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    if len(result) != len(nodes):
        return None

    return result
