import re
from collections import defaultdict


class Spreadsheet:
    def __init__(self):
        self._values = {}  # cell -> raw value (number or formula string)
        self._computed = {}  # cell -> computed number
        self._dependents = defaultdict(set)  # cell -> set of cells that depend on it
        self._dependencies = defaultdict(set)  # cell -> set of cells it depends on
        self._dirty = set()  # cells whose computed value is stale

    def _parse_cell_ref(self, s):
        """Parse a cell reference like 'A1', 'B2', etc."""
        m = re.match(r'^([A-Z]+)(\d+)$', s)
        if m:
            return s
        return None

    def _tokenize_formula(self, formula):
        """Tokenize a formula string into tokens."""
        # Remove the leading '='
        if formula.startswith('='):
            formula = formula[1:]

        tokens = []
        i = 0
        while i < len(formula):
            c = formula[i]
            if c in '+-*/':
                tokens.append(c)
                i += 1
            elif c.isalpha():
                # Cell reference: letters followed by digits
                j = i
                while j < len(formula) and formula[j].isalpha():
                    j += 1
                while j < len(formula) and formula[j].isdigit():
                    j += 1
                tokens.append(formula[i:j])
                i = j
            elif c.isdigit():
                j = i
                while j < len(formula) and formula[j].isdigit():
                    j += 1
                tokens.append(int(formula[i:j]))
                i = j
            else:
                raise ValueError(f"Invalid character in formula: {c}")
        return tokens

    def _parse_formula(self, formula):
        """
        Parse a formula into an AST.
        Returns (ast, dependencies) where ast is a tuple representing the expression
        and dependencies is a set of cell references.

        AST nodes:
        - ('num', value)
        - ('cell', ref)
        - ('binop', op, left, right)
        """
        tokens = self._tokenize_formula(formula)
        if not tokens:
            raise ValueError("Empty formula")

        pos = [0]
        deps = set()

        def parse_expr():
            # expr := term (('+' | '-') term)*
            left = parse_term()
            while pos[0] < len(tokens) and tokens[pos[0]] in ('+', '-'):
                op = tokens[pos[0]]
                pos[0] += 1
                right = parse_term()
                left = ('binop', op, left, right)
            return left

        def parse_term():
            # term := factor (('*') factor)*
            left = parse_factor()
            while pos[0] < len(tokens) and tokens[pos[0]] == '*':
                op = tokens[pos[0]]
                pos[0] += 1
                right = parse_factor()
                left = ('binop', op, left, right)
            return left

        def parse_factor():
            # factor := number | cell_ref | '(' expr ')'
            if pos[0] >= len(tokens):
                raise ValueError("Unexpected end of formula")
            tok = tokens[pos[0]]
            if isinstance(tok, int):
                pos[0] += 1
                return ('num', tok)
            elif isinstance(tok, str) and self._parse_cell_ref(tok):
                pos[0] += 1
                deps.add(tok)
                return ('cell', tok)
            else:
                raise ValueError(f"Unexpected token: {tok}")

        ast = parse_expr()
        if pos[0] != len(tokens):
            raise ValueError("Unexpected tokens remaining")

        return ast, deps

    def _eval_ast(self, ast):
        """Evaluate an AST node, returning a number."""
        if ast[0] == 'num':
            return ast[1]
        elif ast[0] == 'cell':
            return self._get_computed(ast[1])
        elif ast[0] == 'binop':
            _, op, left, right = ast
            lval = self._eval_ast(left)
            rval = self._eval_ast(right)
            if op == '+':
                return lval + rval
            elif op == '-':
                return lval - rval
            elif op == '*':
                return lval * rval
            else:
                raise ValueError(f"Unknown operator: {op}")
        else:
            raise ValueError(f"Unknown AST node: {ast}")

    def _get_computed(self, cell):
        """Get the computed value of a cell, computing it if dirty."""
        if cell not in self._values:
            return 0
        if cell in self._dirty:
            self._recompute(cell)
        return self._computed.get(cell, 0)

    def _recompute(self, cell):
        """Recompute the value of a cell and mark its dependents as dirty."""
        if cell not in self._values:
            self._computed[cell] = 0
            self._dirty.discard(cell)
            return

        value = self._values[cell]
        if isinstance(value, (int, float)):
            self._computed[cell] = value
        else:
            # It's a formula
            ast, deps = self._parse_formula(value)
            self._computed[cell] = self._eval_ast(ast)

        self._dirty.discard(cell)

        # Mark all dependents as dirty
        for dep in self._dependents.get(cell, set()):
            self._dirty.add(dep)

    def _get_dependencies(self, cell):
        """Get all cells that this cell depends on (transitively)."""
        if cell not in self._values:
            return set()
        value = self._values[cell]
        if isinstance(value, (int, float)):
            return set()
        # It's a formula
        _, deps = self._parse_formula(value)
        all_deps = set(deps)
        for d in deps:
            all_deps |= self._get_dependencies(d)
        return all_deps

    def _would_create_cycle(self, cell, new_value):
        """Check if setting cell to new_value would create a reference cycle."""
        if isinstance(new_value, (int, float)):
            return False

        # Get the dependencies of the new formula
        _, new_deps = self._parse_formula(new_value)

        # Check if any of the new dependencies transitively depend on cell
        for dep in new_deps:
            if dep == cell:
                return True
            # Check if dep transitively depends on cell
            if self._transitively_depends_on(dep, cell):
                return True
        return False

    def _transitively_depends_on(self, cell, target):
        """Check if cell transitively depends on target."""
        visited = set()
        stack = [cell]
        while stack:
            c = stack.pop()
            if c == target:
                return True
            if c in visited:
                continue
            visited.add(c)
            if c in self._values:
                value = self._values[c]
                if isinstance(value, str) and value.startswith('='):
                    _, deps = self._parse_formula(value)
                    for d in deps:
                        if d not in visited:
                            stack.append(d)
        return False

    def set(self, cell, value):
        """Set a cell to a value (number or formula string)."""
        # Check for cycles
        if self._would_create_cycle(cell, value):
            raise ValueError("Setting this value would create a reference cycle")

        # Save old state for rollback
        old_value = self._values.get(cell)
        old_computed = self._computed.get(cell)
        old_deps = set(self._dependencies.get(cell, set()))
        old_dependents = set(self._dependents.get(cell, set()))

        # Remove old dependencies
        if old_value is not None and isinstance(old_value, str) and old_value.startswith('='):
            _, old_formula_deps = self._parse_formula(old_value)
            for dep in old_formula_deps:
                self._dependencies[cell].discard(dep)
                self._dependents[dep].discard(cell)

        # Set new value
        self._values[cell] = value

        # Update dependencies
        if isinstance(value, str) and value.startswith('='):
            _, new_deps = self._parse_formula(value)
            self._dependencies[cell] = set(new_deps)
            for dep in new_deps:
                self._dependents[dep].add(cell)
        else:
            self._dependencies[cell] = set()

        # Mark cell and all transitive dependents as dirty
        self._dirty.add(cell)
        self._mark_dependents_dirty(cell)

        # Recompute the cell
        self._recompute(cell)

    def _mark_dependents_dirty(self, cell):
        """Mark all transitive dependents of cell as dirty."""
        stack = [cell]
        while stack:
            c = stack.pop()
            for dep in self._dependents.get(c, set()):
                if dep not in self._dirty:
