function* zipLongest(fill, ...iterables) {
  if (iterables.length === 0) return;

  const iterators = iterables.map((it) => it[Symbol.iterator]());
  const done = iterators.map(() => false);

  while (true) {
    const row = [];
    let anyAlive = false;

    for (let i = 0; i < iterators.length; i++) {
      if (done[i]) {
        row.push(fill);
      } else {
        const result = iterators[i].next();
        if (result.done) {
          done[i] = true;
          row.push(fill);
        } else {
          row.push(result.value);
          anyAlive = true;
        }
      }
    }

    if (!anyAlive) break;

    yield row;
  }
}

module.exports = zipLongest;
