function createStore(reducer, initial) {
  let state = initial;
  let listeners = [];
  let dispatching = false;

  function getState() {
    return state;
  }

  function dispatch(action) {
    if (dispatching) {
      throw new Error('Dispatching while reducing is not allowed');
    }
    dispatching = true;
    try {
      state = reducer(state, action);
    } finally {
      dispatching = false;
    }

    // Snapshot the current list of listeners
    const snapshot = listeners.slice();

    for (let i = 0; i < snapshot.length; i++) {
      const fn = snapshot[i];
      // Check if this listener is still in the current list
      // (it may have been unsubscribed during a previous notification)
      if (listeners.includes(fn)) {
        fn();
      }
    }

    return action;
  }

  function subscribe(fn) {
    listeners.push(fn);
    return function unsubscribe() {
      const idx = listeners.indexOf(fn);
      if (idx !== -1) {
        listeners.splice(idx, 1);
      }
    };
  }

  return {
    getState,
    dispatch,
    subscribe
  };
}

module.exports = createStore;
