function toposortTasks(tasks) {
  return new Promise((resolve, reject) => {
    // Validate all dependencies exist
    for (const [name, task] of Object.entries(tasks)) {
      for (const dep of task.deps) {
        if (!(dep in tasks)) {
          reject(new Error(`Unknown dependency: ${dep}`));
          return;
        }
      }
    }

    // Detect cycles using DFS
    const WHITE = 0, GRAY = 1, BLACK = 2;
    const color = {};
    for (const name of Object.keys(tasks)) {
      color[name] = WHITE;
    }

    function dfs(node, path) {
      color[node] = GRAY;
      path.push(node);
      for (const dep of tasks[node].deps) {
        if (color[dep] === GRAY) {
          // Cycle detected
          const cycleStart = path.indexOf(dep);
          const cycle = path.slice(cycleStart).concat(dep);
          reject(new Error(`Dependency cycle detected: ${cycle.join(' -> ')}`));
          return true;
        }
        if (color[dep] === WHITE) {
          if (dfs(dep, path)) {
            return true;
          }
        }
      }
      path.pop();
      color[node] = BLACK;
      return false;
    }

    for (const name of Object.keys(tasks)) {
      if (color[name] === WHITE) {
        if (dfs(name, [])) {
          return;
        }
      }
    }

    // Now execute tasks
    const results = {};
    const promises = {};
    const inDegree = {};
    const dependents = {}; // dep -> [tasks that depend on it]

    for (const name of Object.keys(tasks)) {
      inDegree[name] = tasks[name].deps.length;
      dependents[name] = [];
    }

    for (const [name, task] of Object.entries(tasks)) {
      for (const dep of task.deps) {
        dependents[dep].push(name);
      }
    }

    // Queue of tasks with inDegree 0
    const queue = [];
    for (const name of Object.keys(tasks)) {
      if (inDegree[name] === 0) {
        queue.push(name);
      }
    }

    let completed = 0;
    const total = Object.keys(tasks).length;
    let hasError = false;
    let firstError = null;

    function runTask(name) {
      const task = tasks[name];
      const depValues = {};
      for (const dep of task.deps) {
        depValues[dep] = results[dep];
      }

      return task.run(depValues).then(value => {
        results[name] = value;
        completed++;
        if (completed === total) {
          if (hasError) {
            reject(firstError);
          } else {
            resolve(results);
          }
        }
        // Trigger dependents
        for (const dependent of dependents[name]) {
          inDegree[dependent]--;
          if (inDegree[dependent] === 0) {
            runTask(dependent);
          }
        }
      }, err => {
        results[name] = err; // Store the error
        completed++;
        if (!hasError) {
          hasError = true;
          firstError = err;
        }
        if (completed === total) {
          reject(firstError);
        }
        // Still trigger dependents so they can complete (they'll get the error as their dep value)
        for (const dependent of dependents[name]) {
          inDegree[dependent]--;
          if (inDegree[dependent] === 0) {
            runTask(dependent);
          }
        }
      });
    }

    // Start all tasks with inDegree 0
    for (const name of queue) {
      runTask(name);
    }

    // If no tasks at all
    if (total === 0) {
      resolve({});
    }
  });
}

module.exports = toposortTasks;
