export class Bus<E extends Record<string, unknown>> {
  private handlers: { [K in keyof E]: Array<(payload: E[K]) => void> } = {} as any;

  on<K extends keyof E>(k: K, fn: (payload: E[K]) => void): () => void {
    if (!this.handlers[k]) {
      this.handlers[k] = [];
    }
    this.handlers[k].push(fn);
    return () => {
      const arr = this.handlers[k];
      const idx = arr.indexOf(fn);
      if (idx !== -1) {
        arr.splice(idx, 1);
      }
    };
  }

  emit<K extends keyof E>(k: K, ...args: E[K] extends void ? [] : [E[K]]): void {
    const arr = this.handlers[k];
    if (!arr) return;
    const payload = args[0] as E[K];
    for (const fn of arr) {
      fn(payload);
    }
  }
}
