type RequiredKeys<T> = {
  [K in keyof T]-?: {} extends Pick<T, K> ? never : K;
}[keyof T];

type OptionalKeys<T> = {
  [K in keyof T]+?: {} extends Pick<T, K> ? K : never;
}[keyof T];

type AllKeys<T> = keyof T;

type IsComplete<T, S> = [RequiredKeys<T>] extends [never]
  ? true
  : [RequiredKeys<T>] extends [keyof S]
    ? true
    : false;

export class Builder<Config, Set = {}> {
  private _data: Record<string, unknown> = {};
  private _built = false;

  set<K extends AllKeys<Config>>(key: K, value: Config[K]): this {
    if (this._built) {
      throw new Error("Builder has already been built");
    }
    this._data[key as string] = value;
    return this as unknown as Builder<Config, Set & { [P in K]: Config[P] }>;
  }

  build(): Config {
    if (this._built) {
      throw new Error("Builder has already been built");
    }
    this._built = true;
    return this._data as Config;
  }
}

export function builder<Config>(): Builder<Config, {}> {
  return new Builder<Config, {}>();
