export type Result<T, E> =
  | { readonly tag: "ok"; readonly value: T }
  | { readonly tag: "err"; readonly error: E };

export function ok<T, E = never>(value: T): Result<T, E> {
  return { tag: "ok", value };
}

export function err<T = never, E>(error: E): Result<T, E> {
  return { tag: "err", error };
}

export function isOk<T, E>(r: Result<T, E>): r is { tag: "ok"; value: T } {
  return r.tag === "ok";
}

export function isErr<T, E>(r: Result<T, E>): r is { tag: "err"; error: E } {
  return r.tag === "err";
}

export function map<T, E, U>(r: Result<T, E>, f: (value: T) => U): Result<U, E> {
  if (r.tag === "ok") {
    return { tag: "ok", value: f(r.value) };
  }
  return r;
}

export function unwrapOr<T, E>(r: Result<T, E>, fallback: T): T {
  if (r.tag === "ok") {
    return r.value;
  }
  return fallback;
}
