type ParamsOf<Path extends string> = Path extends `:${infer P}`
  ? P extends `${infer Name}:${infer Rest}`
    ? { [K in Name]: string } & ParamsOf<Rest>
    : { [K in P]: string }
  : Path extends `/${infer Rest}`
    ? ParamsOf<Rest>
    : {};

type ParamsOfNoLeadingSlash<Path extends string> = Path extends `:${infer P}`
  ? P extends `${infer Name}:${infer Rest}`
    ? { [K in Name]: string } & ParamsOfNoLeadingSlash<Rest>
    : { [K in P]: string }
  : Path extends `/${infer Rest}`
    ? ParamsOfNoLeadingSlash<Rest>
    : {};

type ExtractParams<Path extends string> = Path extends `/${infer Rest}`
  ? ParamsOfNoLeadingSlash<Rest>
  : ParamsOfNoLeadingSlash<Path>;

type HasParams<Path extends string> = ExtractParams<Path> extends Record<string, never>
  ? false
  : true;

type InterpolateFn<Path extends string> = HasParams<Path> extends true
  ? (params: ExtractParams<Path>) => string
  : () => string;

type RouteMap = Record<string, string>;

type RouteFns<Routes extends RouteMap> = {
  [K in keyof Routes]: InterpolateFn<Routes[K]>;
};

export function defineRoutes<Routes extends RouteMap>(routes: Routes): RouteFns<Routes> {
  const result = {} as Record<string, (...args: any[]) => string>;

  for (const [name, path] of Object.entries(routes)) {
    result[name] = (...args: any[]) => {
      let currentPath = path;
      let argIndex = 0;

      // Parse the path and replace :param segments with provided values
      const segments = currentPath.split(/(?=:[a-zA-Z_]\w*)/);
      let interpolated = "";

      for (const segment of segments) {
        if (segment.startsWith(":")) {
          const paramName = segment.slice(1);
          const value = args[argIndex];
          if (typeof value !== "string") {
            throw new Error(`Missing or invalid param: ${paramName}`);
          }
          interpolated += value;
          argIndex++;
        } else {
          interpolated += segment;
        }
      }

      return interpolated;
    };
  }

  return result as unknown as RouteFns<Routes>;
}
