export type DeepPartial<T> = T extends readonly any[]
  ? T
  : T extends (...args: any[]) => any
    ? T
    : T extends object
      ? { [K in keyof T]?: DeepPartial<T[K]> }
      : T;

export function applyPatch<T>(base: T, patch: DeepPartial<T>): T {
  const result = deepMerge(base, patch);
  return result as T;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  if (typeof value !== "object" || value === null) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function deepMerge<T>(base: T, patch: DeepPartial<T>): T {
  if (patch === undefined) {
    return base;
  }

  if (Array.isArray(base) || Array.isArray(patch)) {
    // Arrays are replaced wholesale
    return patch as T;
  }

  if (typeof base === "function" || typeof patch === "function") {
    // Functions are replaced wholesale
    return patch as T;
  }

  if (isPlainObject(base) && isPlainObject(patch)) {
    const result: Record<string, unknown> = { ...base };
    for (const key of Object.keys(patch)) {
      const patchValue = (patch as Record<string, unknown>)[key];
      if (patchValue === undefined) {
        // Explicit undefined means "leave alone"
        continue;
      }
      const baseValue = (base as Record<string, unknown>)[key];
      if (isPlainObject(baseValue) && isPlainObject(patchValue)) {
        result[key] = deepMerge(baseValue, patchValue);
      } else {
        result[key] = patchValue;
      }
    }
    return result as T;
  }

  // Primitives or non-plain objects: replace wholesale
  return patch as T;
}
